G = {}

def bits_of(i, nb):
    return np.array([1.0 if (i >> b) & 1 else -1.0 for b in range(nb)])

def init(layout):
    d = 64
    T = layout['T']
    V = layout['vocab']
    xb = layout['x_base']; yb = layout['y_base']; zb = layout['z_base']; gs = layout['GSEP']
    nb = 5
    npos = 5 * T + 3
    E = np.zeros((V, d))
    for v in range(V):
        if v < yb:
            E[v, 0:nb] = bits_of(v - xb, nb); E[v, 5] = 1.0
        elif v < zb:
            E[v, 0:nb] = bits_of(v - yb, nb); E[v, 6] = 1.0
        elif v < gs:
            E[v, 0:nb] = bits_of(v - zb, nb); E[v, 7] = 1.0
        else:
            E[v, 8] = 1.0
    P = np.zeros((npos, d))
    for t in range(npos):
        P[t, 9] = float(t); P[t, 10] = float(t * t); P[t, 11] = 1.0
    sq = np.sqrt(d)
    K = 50.0
    s = 20.0
    Wa1 = np.zeros((d, d)); Wa1[9, 9] = 1.0; Wa1[10, 10] = 1.0
    Wp1 = np.zeros((d, d)); Wp1[9, 9] = 2 * K * sq; Wp1[9, 11] = -1.5 * K * sq; Wp1[10, 11] = -K * sq
    Wc1 = np.zeros((d, d))
    for b in range(nb):
        Wc1[12 + b, b] = 1.0
    for k in range(4):
        Wc1[17 + k, 5 + k] = 1.0
    Wa2 = np.zeros((d, d))
    for k in range(12, 21):
        Wa2[k, k] = 1.0
    Wp2 = np.zeros((d, d))
    for b in range(nb):
        Wp2[12 + b, b] = s * sq
    Wp2[17, 5] = s * sq
    Wc2 = np.zeros((d, d))
    for b in range(nb):
        Wc2[21 + b, b] = 1.0
    for k in range(4):
        Wc2[26 + k, 5 + k] = 1.0
    I = np.eye(d)
    Z = np.zeros((d, d))
    O = np.zeros((d, V))
    for v in range(V):
        if zb <= v < gs:
            O[21:21 + nb, v] = bits_of(v - zb, nb)
        else:
            O[11, v] = -100.0
    G['E'] = E; G['P'] = P; G['d'] = d
    G['rounds'] = [(Wa1, Wc1, Wp1, I, Z, Z), (Wa2, Wc2, Wp2, I, Z, Z)]
    G['O'] = O
    return {'A1': [], 'C1': [], 'A2': [], 'C2': [], 'h': np.zeros(d), 't': 0}

def retrieve(p, A, C, d):
    Am = np.array(A); Cm = np.array(C)
    sc = Am @ p / np.sqrt(d)
    sc = sc - sc.max()
    w = np.exp(sc)
    w = w / w.sum()
    return w @ Cm

def update(state, token):
    d = G['d']
    t = state['t']
    h = G['E'][token] + G['P'][t]
    keys = [('A1', 'C1'), ('A2', 'C2')]
    for l in range(2):
        Wa, Wc, Wp, Wo, U, Vm = G['rounds'][l]
        ka, kc = keys[l]
        state[ka].append(Wa @ h)
        state[kc].append(Wc @ h)
        r = retrieve(Wp @ h, state[ka], state[kc], d)
        g = h + Wo @ r
        h = g + U @ np.maximum(0.0, Vm @ g)
    state['h'] = h
    state['t'] = t + 1
    return state

def predict(state):
    return int(np.argmax(state['h'] @ G['O']))

